function StoreChest:Awake()
    self.LoopView:InitGridView(0, Bind(self, self.OnRefreshIndex))
    self._onRefreshStore = Bind(self, self.OnRefreshStore)
    Events.AddListener(StoreConstants.StoreEvents.OnRefreshStore, self._onRefreshStore)

    self._tickHandler = Bind(self, self.OnTimeTick)
    StoreShared:RegisterTimer(self._tickHandler)
end

function StoreChest:OnDestroy()
    if self._onRefreshStore ~= nil then
        Events.RemoveListener(StoreConstants.StoreEvents.OnRefreshStore, self._onRefreshStore)
        self._onRefreshStore = nil
    end

    if self._tickHandler ~= nil then
        StoreShared:UnRegisterTimer(self._tickHandler)
    end

    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

function StoreChest:InitData()
    local comp = StoreUtils.GetStoreComp()
    local config = StoreConstants.Config[self._openId]
    ---@type StoreChestDojo[]
    self._storeData = comp.AllStores[config.dataKey]
    self:SortStoreData()
end

---排序
function StoreChest:SortStoreData()
    table.sort(self._storeData, function(a, b)
        local isFreeA = StoreUtils.ProductIsFree(a)
        local isFreeB = StoreUtils.ProductIsFree(b)
        local isSoldOutA = StoreUtils.ProductIsSoldOut(a)
        local isSoldOutB = StoreUtils.ProductIsSoldOut(b)
        if isFreeA ~= isFreeB then
            return isFreeA
        elseif isSoldOutA ~= isSoldOutB then
            return not isSoldOutA
        elseif a.activityUuid ~= b.activityUuid then
            return a.activityUuid > b.activityUuid
        elseif a.pos ~= b.pos then
            return a.pos < b.pos
        else
            return a.productId < b.productId
        end
    end)
end

function StoreChest:OnRefreshStore()
    self:InitData()
    self:RefreshScroll()
end

function StoreChest:RefreshSelf(params)
    self._openId = params.openId or StoreConstants.OpenIds.Gift
    self:InitData()
    self:RefreshScroll()
    
    if params.itemData then
        self.co = cs_coroutine.start(function()
            CfUtils.PlayAnimator(self.Root, "Default")
            StoreUtils.OpenChestBuyDialog(self._openId, params.itemData)
        end)
       
    end 
end

function StoreChest:RefreshScroll()
    --self.LoopView:MovePanelToItemByIndex(0)
    GameUtils.ReloadData(self.LoopView, #self._storeData)
end

