function StoreChest:OnRefreshIndex(listView, index, row, col)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(ItemCell)
    local data = self._storeData[index + 1]
    local chestCellScr = CfUtils.GetLuaScr(cell, ChestCellPath)
    chestCellScr:RefreshCell(self._openId, data)
    return cell
end

function StoreChest:GetChestBuyBtm(isFree)
    if isFree then
        return StoreConstants.ChestFreeBtm
    else
        return StoreConstants.ChestOtherBtm
    end
end

function StoreChest:OnTimeTick()
    --self.LoopView:RefreshAllShownItem()
    local refresh = false
    for i, v in pairs(checkTable(self._storeData)) do
        if v.nextRefreshLeftSeconds == 0 then
            --printInfo(table.)
            refresh = true
            break ;
        end
    end

    if refresh then
        GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                StoreUtils.RefreshStore(response.data)
            end
        end)
        return
    end
    -- 刷新cell
    for i, v in ipairs(self._storeData) do
        local go = self.LoopView:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, ChestCellPath)
            scr:RefreshTimeGroup(v)
        end
    end 
end

return StoreChest